1: // 真实后端请求封装：注入 zhi-project-id 头、Bearer token、解包 {code,msg,data}
2: export interface RequestOptions {
3:   method?: 'GET' | 'POST' | 'PUT' | 'DELETE'
4:   data?: unknown
5:   token?: string | false
6:   projectId?: string
7:   raw?: boolean
8:   baseUrl?: string
9: }
10: export interface TransportInput {
11:   url: string
12:   method: NonNullable<RequestOptions['method']>
13:   data?: unknown
14:   header: Record<string, string>
15:   timeout: number
16: }
17: export type Transport = (input: TransportInput) => Promise<{ statusCode: number; data: unknown }>
18: export interface Envelope<T> { code: number; msg: string; data: T }
19: export interface RequestConfig { baseUrl: string; projectId: string; getToken?: () => string | undefined }
20: 
21: // 兼容旧签名：createRequest(transport, baseUrlString) -> 纯透传旧行为
22: // 新签名：createRequest(transport, configObject) -> 注入头 + 解包
23: export function createRequest(transport: Transport, baseUrlOrConfig: string | RequestConfig) {
24:   const legacy = typeof baseUrlOrConfig === 'string'
25:   const config: RequestConfig = legacy ? { baseUrl: baseUrlOrConfig, projectId: 'suzhufang' } : baseUrlOrConfig
26:   return async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
27:     const baseUrl = options.baseUrl ?? config.baseUrl
28:     if (!baseUrl) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
29:     const header: Record<string, string> = { 'Content-Type': 'application/json' }
30:     if (!legacy) {
31:       const useToken = options.token === false ? undefined : (options.token || config.getToken?.())
32:       header['zhi-project-id'] = options.projectId ?? config.projectId
33:       if (useToken) header.Authorization = `Bearer ${useToken}`
34:     } else if (options.token) {
35:       header.Authorization = `Bearer ${options.token}`
36:     }
37:     const response = await transport({
38:       url: `${baseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`,
39:       method: options.method ?? 'GET',
40:       data: options.data,
41:       header,
42:       timeout: 20000,
43:     })
44:     if (response.statusCode < 200 || response.statusCode >= 300) {
45:       const body = response.data as Envelope<unknown> | undefined
46:       const msg = body && typeof body === 'object' && 'msg' in body ? String(body.msg) : ''
47:       throw new Error(msg || `请求失败（HTTP ${response.statusCode}）`)
48:     }
49:     if (legacy || options.raw) return response.data as T
50:     const body = response.data as Envelope<T>
51:     if (body && typeof body === 'object' && 'code' in body) {
52:       if (body.code !== 200) throw new Error(body.msg || `业务异常（code ${body.code}）`)
53:       return body.data
54:     }
55:     return response.data as T
56:   }
57: }
58: 
59: export const uniTransport: Transport = input => new Promise((resolve, reject) => {
60:   uni.request({
61:     url: input.url,
62:     method: input.method as never,
63:     data: input.data as Record<string, unknown> | undefined,
64:     header: input.header,
65:     timeout: input.timeout,
66:     success: result => resolve({ statusCode: result.statusCode, data: result.data }),
67:     fail: result => reject(new Error(result.errMsg?.includes('timeout') ? '请求超时，请重试' : '网络连接失败，请重试')),
68:   })
69: })
