72: export function getToken(): string | undefined {
73:   try { const t = uni.getStorageSync(TOKEN_KEY); return typeof t === 'string' && t ? t : undefined } catch { return undefined }
74: }
75: export function setToken(token: string) { try { uni.setStorageSync(TOKEN_KEY, token) } catch { /* ignore */ } }
76: export function clearToken() { try { uni.removeStorageSync(TOKEN_KEY) } catch { /* ignore */ } }
77: 
78: const env = import.meta.env as Record<string, string | undefined>
79: export function isConfigured() { return Boolean(env.VITE_API_BASE_URL) }
80: // flood 服务（9610）
81: export const request = createRequest(uniTransport, {
82:   baseUrl: env.VITE_API_BASE_URL ?? '',
83:   projectId: env.VITE_PROJECT_ID ?? 'suzhufang',
84:   getToken,
85: })
