166:     async function submitInspectionRemote(kind: InspectionType, values: FormValues): Promise<FloodRecord> {
167:       if (!isConfigured()) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
168:       // values 约定：{ eventId, complexId, checkDate?, haveDanger?, items: FloodItem[] 或 {templateItemId->value} }
169:       if (!values.eventId) throw new Error('缺少预警事件')
170:       if (!values.complexId) throw new Error('请选择物业管理区域')
171:       const items = normalizeItems(values)
172:       if (items.length === 0) throw new Error('请至少填写一个检查项')
173:       const payload = {
174:         inspectionStage: STAGE[kind],
175:         subject: 'property',
176:         // Long 雪花ID(19位) > 2^53，必须用字符串传递，禁止 Number() 以免末位精度丢失
177:         eventId: String(values.eventId),
178:         complexId: String(values.complexId),
179:         haveDanger: values.haveDanger != null ? String(values.haveDanger) : '0',
180:         checkDate: values.checkDate || undefined,
181:         items: items.map(it => ({ templateItemId: String(it.templateItemId), fillType: it.fillType, fillValue: it.value })),
182:       }
183:       const saved = await request<number | string>('/v2.0/safety/flood/inspection/save', { method: 'POST', data: payload })
184:       await request('/v2.0/safety/flood/inspection/submit', { method: 'POST', data: { id: String(saved) } })
185:       const record = await getRecordAsync(String(saved), kind)
186:       if (record) { try { const d = read(); delete d.drafts[kind]; storage.set(key, d) } catch { /* ignore */ } return record }
187:       return { id: String(saved), kind, status: 'submitted', createdAt: new Date().toISOString(), complexId: String(values.complexId), eventId: String(values.eventId), items }
188:     }
189: 
190:     function normalizeItems(values: FormValues): FloodItem[] {
191:       const raw = values.items
192:       if (Array.isArray(raw)) return (raw as FloodItem[]).filter(it => it && it.templateItemId)
193:       // 也接受模板表单直接塞 FloodItem[]
194:       return []
195:     }
196: 
197:     function getRecord(id: string) { return read().records?.find(record => record.id === id) ?? null }
198:     function getDraftByKey(id: string) {
199:       if (!id.startsWith('draft-')) return null
200:       const kind = id.slice(6) as InspectionType
201:       if (kind !== 'pre' && kind !== 'mid' && kind !== 'post') return null
202:       const entry = read().drafts[kind]
203:       if (!entry) return null
204:       const draft = normalizeDraft(entry)
205:       return { id, kind, status: 'draft' as const, values: draft.values, createdAt: draft.savedAt } satisfies FloodRecord
206:     }
207:     function localDrafts(query: HistoryQuery): FloodRecord[] {
208:       const data = read()
209:       return Object.entries(data.drafts).map(([kind, entry]) => {
210:         const draft = normalizeDraft(entry)
211:         return { id: `draft-${kind}`, kind: kind as InspectionType, status: 'draft' as const, values: draft.values, createdAt: draft.savedAt }
212:       }).filter(item => query.kinds.includes(item.kind) && (query.status === 'all' || item.status === query.status) && (!query.keyword || JSON.stringify(item.values).includes(query.keyword)))
213:     }
