217:     }
218:     async function fetchHistoryPage(query: HistoryQuery & { pageNum: number; pageSize: number }) {
219:       if (isRemote) return await fetchHistoryRemote(query)
220:       const all = matchQuery(query)
221:       const start = (query.pageNum - 1) * query.pageSize
