245:         items.push(...(page.rows ?? []).map(rescueRowToRecord))
246:         total += Number(page.total ?? 0)
247:       }
248:       const hasMore = query.pageNum * query.pageSize < total
249:       return { items, total, hasMore }
250:     }
251:     async function countHistory(query: HistoryQuery) {
252:       if (isRemote) {
253:         // 计数只取后端 total（pageSize=1 即可，避免为计数拉全量），按阶段/求援分别累计
254:         const inspectionKinds = query.kinds.filter(k => k !== 'rescue') as InspectionType[]
255:         let total = 0
