57:     public GatewayFilter apply(Object config) {
58:         return (exchange, chain) -> {
59:             ServerHttpRequest request = exchange.getRequest();
60:             if ( !captchaProperties.getEnabled() ) {
61:                 return chain.filter(exchange);
62:             }
63: 
64:             // 非登录/注册请求或验证码关闭，不处理
65:             String path = request.getURI().getPath();
