82:         // 获取请求体
83:         Flux<DataBuffer> body = serverHttpRequest.getBody();
84:         AtomicReference<String> bodyRef = new AtomicReference<>();
85:         body.subscribe(buffer -> {
86:             CharBuffer charBuffer = StandardCharsets.UTF_8.decode(buffer.asByteBuffer());
87:             DataBufferUtils.release(buffer);
88:             bodyRef.set(charBuffer.toString());
89:         });
