const env = import.meta.env as Record<string, string | undefined>
export function isConfigured() {
  return Boolean(env.VITE_API_BASE_URL || env.VITE_AUTH_BASE_URL)
}

/** 网关图形验证码：GET /v2.0/code（CaptchaValidateFilter 校验 login 请求体中的 code + uuid） */
export interface LoginCaptchaPayload {
  enabled: boolean
  uuid?: string
  imageDataUrl?: string
}

export async function fetchLoginCaptcha(): Promise<LoginCaptchaPayload> {
  const baseUrl = env.VITE_AUTH_BASE_URL ?? ''
  if (!baseUrl) throw new Error('真实接口未配置：请设置 VITE_AUTH_BASE_URL')
  const url = `${baseUrl.replace(/\/$/, '')}/v2.0/code`
  const response = await uniTransport({
    url,
    method: 'GET',
    header: { Accept: 'application/json, text/plain, */*', 'zhi-project-id': env.VITE_PROJECT_ID ?? 'suzhufang' },
    timeout: 20000,
  })
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`验证码加载失败（HTTP ${response.statusCode}）`)
  }
  const body = response.data as {
    code?: number
    msg?: string
    captchaOnOff?: boolean
    uuid?: string
    data?: string
  } | null
  if (body && typeof body === 'object' && 'code' in body && body.code !== 200) {
    throw new Error(body.msg || '验证码加载失败')
  }
  const enabled = body?.captchaOnOff !== false && Boolean(body?.uuid && body?.data)
  if (!enabled) return { enabled: false }
  const raw = String(body!.data)
  const imageDataUrl = raw.startsWith('data:') ? raw : `data:image/jpeg;base64,${raw}`
  return { enabled: true, uuid: String(body!.uuid), imageDataUrl }
}

